import { request, streamUrl } from "../api/client";

const MAX_TRADES = 80;
const FALLBACK_UNIVERSE = [
  { symbol: "BTC/USDT", perp_symbol: "BTC/USDT:USDT", source: "frontend_fallback" },
  { symbol: "ETH/USDT", perp_symbol: "ETH/USDT:USDT", source: "frontend_fallback" },
